import React, { useState } from 'react';

const Navbar = () => {
  const [lang, setLang] = useState('mg');

  return (
    <nav className="bg-white border-b border-gray-200 fixed w-full z-30 top-0">
      <div className="px-4 py-3 lg:px-6">
        <div className="flex items-center justify-between">
          <div className="flex items-center">
            <span className="self-center text-xl font-bold sm:text-2xl whitespace-nowrap text-indigo-600">
              🇲🇬 Mpanolo-tsaina <span className="text-gray-800 text-sm font-medium italic">AI</span>
            </span>
          </div>

          <div className="flex items-center gap-4">
            {/* Sélecteur de langue */}
            <select 
              value={lang} 
              onChange={(e) => setLang(e.target.value)}
              className="bg-gray-50 border border-gray-300 text-gray-900 text-sm rounded-lg p-1.5 focus:ring-indigo-500"
            >
              <option value="mg">Malagasy</option>
              <option value="fr">Français</option>
            </select>

            {/* Bouton Profil */}
            <button className="flex text-sm bg-gray-800 rounded-full focus:ring-4 focus:ring-gray-300">
              <div className="h-8 w-8 rounded-full bg-indigo-500 flex items-center justify-center text-white">
                <span className="font-bold">U</span>
              </div>
            </button>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;
